import pyomo.environ as pyo

DATA = {
    "Cities": ["A", "B"],
    "Links": [["A", "B"]],
    "Products": ["Product1"],
    "Supply": [[10], [0]],
    "Demand": [[0], [10]],
    "ShipmentCost": [[[1]]],
    "Capacity": [[[10]]],
    "JointCapacity": [[10]],
}


def build_model(data=None):
    d = data or DATA

    cities = list(d["Cities"])
    products = list(d["Products"])
    city_index = {c: k for k, c in enumerate(cities)}
    prod_index = {p: k for k, p in enumerate(products)}

    # Directed links that exist
    link_list = [(i, j) for (i, j) in d["Links"]]

    model = pyo.ConcreteModel()

    model.Cities = pyo.Set(initialize=cities)
    model.Products = pyo.Set(initialize=products)
    model.Links = pyo.Set(initialize=link_list, dimen=2)

    # ---- Flow variables: packages of product p on link (i,j) ----
    def ship_bounds(m, i, j, p):
        return (0, d["Capacity"][city_index[i]][city_index[j]][prod_index[p]])

    model.ship = pyo.Var(
        model.Links,
        model.Products,
        domain=pyo.NonNegativeIntegers,
        bounds=ship_bounds,
    )

    # ---- Objective: minimize total shipping cost ----
    def obj_rule(m):
        return sum(
            d["ShipmentCost"][city_index[i]][city_index[j]][prod_index[p]]
            * m.ship[i, j, p]
            for (i, j) in link_list
            for p in products
        )

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # ---- Supply limit: total shipped out of city i (product p) <= Supply ----
    def supply_rule(m, i, p):
        return (
            sum(m.ship[i, j, p] for (a, j) in link_list if a == i)
            <= d["Supply"][city_index[i]][prod_index[p]]
        )

    model.supply_limit = pyo.Constraint(model.Cities, model.Products, rule=supply_rule)

    # ---- Demand satisfaction: total shipped into city j (product p) >= Demand ----
    def demand_rule(m, j, p):
        return (
            sum(m.ship[i, jj, p] for (i, jj) in link_list if jj == j)
            >= d["Demand"][city_index[j]][prod_index[p]]
        )

    model.demand_satisfy = pyo.Constraint(model.Cities, model.Products, rule=demand_rule)

    # ---- Joint capacity: total packages on link (i,j) <= JointCapacity ----
    def joint_rule(m, i, j):
        return (
            sum(m.ship[i, j, p] for p in products)
            <= d["JointCapacity"][city_index[i]][city_index[j]]
        )

    model.joint_capacity = pyo.Constraint(model.Links, rule=joint_rule)

    return model


