def _build_lookup(data_lists, cities, products, default=0):
    out = {}
    for i, ci in enumerate(cities):
        inner = {}
        for p, pj in enumerate(products):
            if i < len(data_lists) and data_lists[i] is not None and p < len(data_lists[i]):
                inner[pj] = data_lists[i][p]
            else:
                inner[pj] = default
        out[ci] = inner
    return out


def build_model(data=None):
    d = data or DATA

    cities = list(d["Cities"])
    products = list(d["Products"])
    links = [tuple(lk) for lk in d["Links"]]

    supply = _build_lookup(d["Supply"], cities, products, 0)
    demand = _build_lookup(d["Demand"], cities, products, 0)

    # shipment_cost[(i, j, p)]
    shipment_cost = {}
    for idx_i, i in enumerate(cities):
        for idx_j, j in enumerate(cities):
            for idx_p, p in enumerate(products):
                val = 0
                if idx_i < len(d["ShipmentCost"]) and d["ShipmentCost"][idx_i] is not None:
                    if idx_j < len(d["ShipmentCost"][idx_i]) and d["ShipmentCost"][idx_i][idx_j] is not None:
                        if idx_p < len(d["ShipmentCost"][idx_i][idx_j]):
                            val = d["ShipmentCost"][idx_i][idx_j][idx_p]
                shipment_cost[(i, j, p)] = val

    # capacity[(i, j, p)] and joint_capacity[(i, j)]
    capacity = {}
    joint_capacity = {}
    for idx_i, i in enumerate(cities):
        for idx_j, j in enumerate(cities):
            for idx_p, p in enumerate(products):
                val = 0
                if idx_i < len(d["Capacity"]) and d["Capacity"][idx_i] is not None:
                    if idx_j < len(d["Capacity"][idx_i]) and d["Capacity"][idx_i][idx_j] is not None:
                        if idx_p < len(d["Capacity"][idx_i][idx_j]):
                            val = d["Capacity"][idx_i][idx_j][idx_p]
                capacity[(i, j, p)] = val
            jval = 0
            if idx_i < len(d["JointCapacity"]) and d["JointCapacity"][idx_i] is not None:
                if idx_j < len(d["JointCapacity"][idx_i]):
                    jval = d["JointCapacity"][idx_i][idx_j]
            joint_capacity[(i, j)] = jval

    model = pyo.ConcreteModel()

    model.C = pyo.Set(initialize=cities)
    model.P = pyo.Set(initialize=products)
    model.L = pyo.Set(initialize=links, dimen=2)

    index_triples = [(i, j, p) for (i, j) in links for p in products]

    def x_bounds(m, i, j, p):
        return (0, capacity.get((i, j, p), 0))

    model.x = pyo.Var(
        index_triples,
        domain=pyo.NonNegativeIntegers,
        bounds=x_bounds,
    )

    def obj_rule(m):
        return sum(shipment_cost[(i, j, p)] * m.x[i, j, p] for (i, j, p) in index_triples)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Supply: outflow <= supply per city/product
    def supply_rule(m, i, p):
        total_out = sum(m.x[ii, jj, p] for (ii, jj) in links if ii == i)
        return total_out <= supply[i][p]

    model.supply_con = pyo.Constraint(model.C, model.P, rule=supply_rule)

    # Demand: inflow >= demand per city/product
    def demand_rule(m, j, p):
        total_in = sum(m.x[ii, jj, p] for (ii, jj) in links if jj == j)
        return total_in >= demand[j][p]

    model.demand_con = pyo.Constraint(model.C, model.P, rule=demand_rule)

    # Per-product link capacity
    def cap_rule(m, i, j, p):
        return m.x[i, j, p] <= capacity.get((i, j, p), 0)

    model.cap_con = pyo.Constraint(index_triples, rule=cap_rule)

    # Joint link capacity across all products
    def joint_rule(m, i, j):
        total = sum(m.x[i, j, p] for p in products)
        return total <= joint_capacity.get((i, j), 0)

    model.joint_con = pyo.Constraint(model.L, rule=joint_rule)

    return model


