    products = list(d['Products'])
    links = [(a, b) for a, b in d['Links']]

    cpos = {c: k for k, c in enumerate(cities)}
    ppos = {p: k for k, p in enumerate(products)}

    def supply(i, p):
        return d['Supply'][cpos[i]][ppos[p]]

    def demand(j, p):
        return d['Demand'][cpos[j]][ppos[p]]

    def shipcost(i, j, p):
        return d['ShipmentCost'][cpos[i]][cpos[j]][ppos[p]]

    def capacity(i, j, p):
        return d['Capacity'][cpos[i]][cpos[j]][ppos[p]]

    def jointcap(i, j):
        return d['JointCapacity'][cpos[i]][cpos[j]]

    ub = {}
    for (i, j) in links:
        jc = jointcap(i, j)
        for p in products:
            pc = capacity(i, j, p)
            ub[(i, j, p)] = min(pc, jc)

    model = pyo.ConcreteModel()

    model.Cities = pyo.Set(initialize=cities)
    model.Products = pyo.Set(initialize=products)
    model.Links = pyo.Set(initialize=links, dimen=2)

    def x_index_init(m):
        for (i, j) in links:
            for p in products:
                yield (i, j, p)

    model.IFJ = pyo.Set(initialize=list(x_index_init(model)), dimen=3)

    def x_bounds(m, i, j, p):
        return (0, ub[(i, j, p)])

    model.x = pyo.Var(
        model.IFJ,
        within=pyo.NonNegativeIntegers,
        bounds=x_bounds,
    )

    def obj_rule(m):
        return sum(
            shipcost(i, j, p) * m.x[i, j, p]
            for (i, j, p) in m.IFJ
        )

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def supply_rule(m, i, p):
        outflow = sum(
            m.x[i, k, p] for (a, k, q) in m.IFJ if a == i and q == p
        )
        return outflow <= supply(i, p)

    model.supply_con = pyo.Constraint(model.Cities, model.Products,
                                      rule=supply_rule)

    def demand_rule(m, j, p):
        inflow = sum(
            m.x[k, j, p] for (k, b, q) in m.IFJ if b == j and q == p
        )
        return inflow >= demand(j, p)

    model.demand_con = pyo.Constraint(model.Cities, model.Products,
                                      rule=demand_rule)

    def link_prod_cap_rule(m, i, j, p):
        return m.x[i, j, p] <= capacity(i, j, p)

    model.link_prod_cap = pyo.Constraint(model.IFJ, rule=link_prod_cap_rule)

    def joint_cap_rule(m, i, j):
        return sum(m.x[i, j, p] for p in m.Products) <= jointcap(i, j)

    model.joint_cap = pyo.Constraint(model.Links, rule=joint_cap_rule)

    return model

