def build_model(data=None):
    d = data or DATA

    cities = list(d["Cities"])
    products = list(d["Products"])
    # Directed links as (origin, destination) tuples.
    links = [(a, b) for a, b in d["Links"]]

    # Index maps to look up nested-list data by name.
    cidx = {c: k for k, c in enumerate(cities)}
    pidx = {p: k for k, p in enumerate(products)}

    def supply(c, p):
        return d["Supply"][cidx[c]][pidx[p]]

    def demand(c, p):
        return d["Demand"][cidx[c]][pidx[p]]

    def ship_cost(i, j, p):
        return d["ShipmentCost"][cidx[i]][cidx[j]][pidx[p]]

    def cap(i, j, p):
        return d["Capacity"][cidx[i]][cidx[j]][pidx[p]]

    def joint_cap(i, j):
        return d["JointCapacity"][cidx[i]][cidx[j]]

    model = pyo.ConcreteModel()

    # Sets
    model.Cities = pyo.Set(initialize=cities)
    model.Products = pyo.Set(initialize=products)
    model.Links = pyo.Set(initialize=links, dimen=2)

    # Decision variable: packages of product p on link (i, j).
    model.x = pyo.Var(
        model.Links,
        model.Products,
        domain=pyo.NonNegativeReals,
    )

    # Objective: minimize total shipping cost.
    def obj_rule(m):
        return sum(
            ship_cost(i, j, p) * m.x[i, j, p]
            for (i, j) in links
            for p in products
        )

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Per-product link capacity: x[i,j,p] <= Capacity[i][j][p].
    def product_cap_rule(m, i, j, p):
        return m.x[i, j, p] <= cap(i, j, p)

    model.product_cap = pyo.Constraint(
        model.Links, model.Products, rule=product_cap_rule
    )

    # Joint link capacity: sum_p x[i,j,p] <= JointCapacity[i][j].
    def joint_cap_rule(m, i, j):
        return sum(m.x[i, j, p] for p in products) <= joint_cap(i, j)

    model.joint_cap = pyo.Constraint(model.Links, rule=joint_cap_rule)

    # Supply balance: total shipped out of city i for product p <= Supply[i][p].
    def supply_rule(m, i, p):
        return sum(
            m.x[i, j, p] for (a, j) in links if a == i
        ) <= supply(i, p)

    model.supply = pyo.Constraint(model.Cities, model.Products, rule=supply_rule)

    # Demand balance: total shipped into city j for product p >= Demand[j][p].
    def demand_rule(m, j, p):
        return sum(
            m.x[i, j, p] for (i, b) in links if b == j
        ) >= demand(j, p)

    model.demand = pyo.Constraint(model.Cities, model.Products, rule=demand_rule)

    return model
